export function normalizeJobs(jobs) {
  const normalized = [];

  for (const job of jobs) {
    if (
      job !== null &&
      typeof job === 'object' &&
      typeof job.id === 'string' &&
      job.id.length > 0 &&
      Number.isInteger(job.duration) &&
      job.duration > 0
    ) {
      normalized.push({ id: job.id, duration: job.duration });
    }
  }

  return normalized;
}

export function scheduleJobs(jobs) {
  const availability = [0, 0];
  const scheduled = [];

  for (const job of jobs) {
    const slot = availability[0] <= availability[1] ? 0 : 1;
    const start = availability[slot];
    const end = start + job.duration;

    scheduled.push({ id: job.id, start, end, slot });
    availability[slot] = end;
  }

  return scheduled;
}

