  const jobs = Object.freeze([
    Object.freeze({ id: 'duplicate', duration: 3, priority: 1 }),
    null,
    undefined,
    'job',
    Object.freeze({ id: '', duration: 1 }),
    Object.freeze({ id: 4, duration: 1 }),
