    Object.freeze({ id: 'fraction', duration: 1.5 }),
    Object.freeze({ id: 'infinity', duration: Infinity }),
    Object.freeze({ id: 'nan', duration: NaN }),
    Object.freeze({ id: 'missing' }),
    Object.freeze({ id: 'duplicate', duration: 1, priority: 100 }),
    Object.freeze({ id: ' ', duration: 2 }),
  ]);
  const before = structuredClone(jobs);
  const normalized = normalizeJobs(jobs);

  assert.deepEqual(normalized, [
    { id: 'duplicate', duration: 3 },
    { id: 'duplicate', duration: 1 },
    { id: ' ', duration: 2 },
  ]);
