export function encodeCell(value) {
  const cell = value == null ? '' : String(value);
  return /[\t"\r\n]/.test(cell)
    ? `"${cell.replaceAll('"', '""')}"`
    : cell;
}

export function encodeTable(rows) {
  return rows.map(row => row.map(encodeCell).join('\t')).join('\r\n');
}

