test('converts nullish values to empty strings and other values with String', () => {
  for (const [value, expected] of [
    [null, ''], [undefined, ''], ['', ''], [0, '0'], [false, 'false'],
    [42n, '42'], [Symbol('cell'), 'Symbol(cell)'],
    [{ toString: () => 'custom value' }, 'custom value'],
  ]) {
