  }
});

test('quotes tab, double quote, CR and LF and doubles embedded quotes', () => {
  for (const [value, expected] of [
    ['a\tb', '"a\tb"'],
    ['a"b', '"a""b"'],
    ['a\rb', '"a\rb"'],
    ['a\nb', '"a\nb"'],
    ['a\r\nb', '"a\r\nb"'],
    ['"', '""""'],
    ['"a"\t\r\n', '"""a""\t\r\n"'],
    [{ toString: () => 'x\ty"z' }, '"x\ty""z"'],
  ]) {
    assert.equal(encodeCell(value), expected);
  }
});

test('encodes table cells with tabs and records with CRLF without an appended newline', () => {
