      ['a\tb', 'a"b', 'a\rb', 'a\nb', 'a\r\nb', 'a,b'],
    ]),
    '\t\t0\tfalse\t42\tSymbol(cell)\r\n"a\tb"\t"a""b"\t"a\rb"\t"a\nb"\t"a\r\nb"\ta,b',
