import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import test from 'node:test';
import { findMatches, normalizeQuery } from './lib.mjs';

test('normalizeQuery trims and lowercases primitive strings only', () => {
  assert.equal(normalizeQuery(' \tHeLLo\n'), 'hello');
  for (const query of ['', ' \t\n', null, undefined, 42, false, {}, [],
    new String('Hello'), Symbol('hello'), 1n, () => 'hello']) {
    assert.equal(normalizeQuery(query), '');
  }
});

test('normalization preserves accents and distinct Unicode representations', () => {
  assert.equal(normalizeQuery(' CAFÉ '), 'café');
  assert.equal(normalizeQuery(' CAFE\u0301 '), 'cafe\u0301');
  assert.notEqual(normalizeQuery('É'), normalizeQuery('E\u0301'));
});

test('matching preserves input order, returns original objects, and caps at two', () => {
  const items = [{ label: 'zebrA' }, { label: 'APPLE' }, { label: 'maple' }];
  const matches = findMatches(items, ' \tA\n');
  assert.equal(matches.length, 2);
  assert.strictEqual(matches[0], items[0]);
  assert.strictEqual(matches[1], items[1]);
  assert.notStrictEqual(matches, items);
});

test('non-string and absent labels are skipped without consuming the limit', () => {
  const first = { label: 'Tea' };
  const second = { label: 'TEAPOT' };
  const items = [null, undefined, {}, { label: null }, { label: 123 },
    { label: false }, { label: new String('Tea') }, { label: Symbol('Tea') },
    { label: ['Tea'] }, { label: 'coffee' }, first, second];
  const matches = findMatches(items, 'tea');
  assert.deepEqual(matches, [first, second]);
  assert.strictEqual(matches[0], first);
  assert.strictEqual(matches[1], second);
});

test('empty and non-string queries return no results', () => {
  const items = [{ label: '' }, { label: 'anything' }];
  for (const query of ['', ' \t\n', null, undefined, 0, false, {}, [],
    new String('anything'), Symbol('anything')]) {
    assert.deepEqual(findMatches(items, query), []);
  }
  assert.deepEqual(findMatches([], 'anything'), []);
  assert.deepEqual(findMatches(items, 'missing'), []);
});

test('matches literal substrings without fuzzy matching or regex interpretation', () => {
  const items = [{ label: 'APPLE' }, { label: 'a.c' }, { label: 'ABC' },
    { label: 'C++' }];
  assert.deepEqual(findMatches(items, 'ppl'), [items[0]]);
  assert.deepEqual(findMatches(items, 'aple'), []);
  assert.deepEqual(findMatches(items, 'a.c'), [items[1]]);
  assert.deepEqual(findMatches(items, '++'), [items[3]]);
});

test('matching distinguishes accents and composed/decomposed Unicode', () => {
  const items = [{ label: 'CAFÉ' }, { label: 'CAFE\u0301' }, { label: 'cafe' }];
  assert.deepEqual(findMatches(items, 'é'), [items[0]]);
  assert.deepEqual(findMatches(items, 'e\u0301'), [items[1]]);
  assert.deepEqual(findMatches(items, 'cafe'), [items[1], items[2]]);
});

test('matching does not mutate frozen inputs or nested item data', () => {
  const items = Object.freeze([
    Object.freeze({ label: 'Beta', metadata: Object.freeze({ rank: 1 }) }),
    Object.freeze({ label: 'Alpha', metadata: Object.freeze({ rank: 2 }) }),
    Object.freeze({ label: 'Gamma', metadata: Object.freeze({ rank: 3 }) }),
  ]);
  const before = structuredClone(items);
  const matches = findMatches(items, 'a');
  assert.deepEqual(items, before);
  assert.strictEqual(matches[0], items[0]);
  assert.strictEqual(matches[1], items[1]);
  matches.pop();
  assert.deepEqual(items, before);
});

test('recovery records the final contract, completed functions, and deferred feature', () => {
  const recovery = JSON.parse(readFileSync(new URL('./recovery.json', import.meta.url), 'utf8'));
  assert.deepEqual(recovery.contract, {
    limit: 2, order: 'input', query: 'trim-lowercase', empty: 'no-results',
  });
  assert.deepEqual(recovery.deferred, ['FUZZY_SEARCH']);
  assert.deepEqual(recovery.completed, ['normalizeQuery', 'findMatches']);
  assert.ok(Array.isArray(recovery.unresolved));
});

